const HIRING_CSS=":root{--hw:#f5f7fa;--ink:#1a3142;--nav:#142b3b;--ocean:#176796;--teal:#1c8c8d;--line:#e1e8ee;--muted:#748393;--sun:#d99c4a;--bad:#be5f4e;--radius:13px}*{box-sizing:border-box}body{margin:0;background:var(--hw);color:var(--ink);font:13px/1.5 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,[draggable]:focus-visible{outline:3px solid #83c5e0;outline-offset:2px}.hw-shell{display:grid;grid-template-columns:228px minmax(0,1fr);min-height:100vh}.hw-sidebar{background:#172c3c;color:#cdd9e2;padding:26px 17px;display:flex;flex-direction:column;gap:14px}.hw-headbrand{padding:3px 10px 24px;border-bottom:1px solid #ffffff1b}.hw-appbrand{font-size:17px;font-weight:780;line-height:1.2;color:white;letter-spacing:-.4px}.hw-appbrand small{display:block;text-transform:uppercase;letter-spacing:1.6px;color:#81adb9;font-weight:700;font-size:9px;margin-bottom:9px}.hw-railcaption{text-transform:uppercase;font-size:9px;letter-spacing:1.6px;color:#85a3b5;font-weight:760;margin:12px 10px 5px}.hw-nav{display:flex;flex-direction:column;gap:3px}.hw-nav button{display:flex;align-items:center;gap:11px;border:0;background:transparent;color:#a8bdca;text-align:left;width:100%;border-radius:8px;padding:11px 12px;font-weight:550;font-size:12px}.hw-nav button.current{background:#ffffff18;color:#fff;font-weight:750}.hw-nav button svg{opacity:.85}.hw-rail-foot{margin-top:auto;border-top:1px solid #ffffff1b;padding:16px 10px 0;color:#93acbc;font-size:10px}.hw-rail-foot b{display:block;color:#d8e5ee;font-weight:600}.hw-main{min-width:0;padding:33px clamp(18px,3.4vw,52px) 55px;max-width:1580px;width:100%;margin:0 auto}.hw-top{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:23px}.hw-kicker{letter-spacing:2px;text-transform:uppercase;color:var(--ocean);font-size:10px;font-weight:760}.hw-top h1{font-size:clamp(25px,3vw,36px);line-height:1.16;letter-spacing:-1.2px;margin:6px 0 6px}.hw-sub{color:#738290;margin:0;font-size:12px}.hw-top-actions{display:flex;gap:9px;align-items:center;flex-shrink:0}.hw-btn{border:1px solid #d6e1e9;color:#344b5d;background:white;border-radius:8px;padding:9px 12px;font-weight:680;display:inline-flex;align-items:center;gap:7px;white-space:nowrap}.hw-btn.primary{background:#166b98;border-color:#166b98;color:white}.hw-btn.ghost{background:transparent}.hw-btn.small{font-size:11px;padding:7px 10px}.hw-ico{display:inline-flex;align-items:center;justify-content:center;width:35px;height:35px;border:1px solid #d9e2ea;border-radius:8px;background:white;color:#4c6373}.hw-panel{background:white;border:1px solid var(--line);border-radius:12px;box-shadow:0 3px 11px #2c506309}.hw-pad{padding:20px}.hw-section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}.hw-section-head h2{font-size:14px;font-weight:750;margin:0;letter-spacing:-.25px}.hw-section-head p{margin:3px 0 0;color:#84919c;font-size:11px}.hw-section-head select{width:auto}.hw-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.hw-hero{grid-column:span 1;background:linear-gradient(130deg,#213b50,#142b3d);border:1px solid #314b5f;color:white;padding:23px;position:relative;overflow:hidden;min-height:173px}.hw-hero:after{content:'';position:absolute;width:210px;height:210px;right:-82px;top:-98px;border:1px solid #ffffff24;border-radius:50%;box-shadow:0 0 0 28px #ffffff09,0 0 0 56px #ffffff06}.hw-hero small{display:block;color:#a9c9d7;text-transform:uppercase;letter-spacing:1.3px;font-size:10px;font-weight:760}.hw-big{font-size:36px;letter-spacing:-1.8px;line-height:1.2;font-weight:770;margin:14px 0 6px}.hw-hero p{font-size:11px;color:#bad0da;margin:0}.hw-metric{padding:23px;min-height:173px}.hw-metric .label{color:#73869b;font-weight:680;font-size:11px}.hw-metric strong{display:block;font-size:31px;letter-spacing:-1.4px;margin:15px 0 8px}.hw-metric small{color:#8b99a5}.hw-badtext{color:var(--bad)!important}.hw-goodtext{color:#1a8a7f!important}.hw-grid2{display:grid;grid-template-columns:1.45fr 1fr;gap:14px;margin-top:15px}.hw-gridEqual{display:grid;grid-template-columns:1fr 1fr;gap:14px}.hw-pill{display:inline-block;padding:4px 8px;border-radius:20px;background:#edf4f8;color:#3d6d85;font-size:10px;font-weight:730;white-space:nowrap}.hw-pill.warn{background:#fff3e1;color:#9a6b26}.hw-pill.red{background:#fff0ed;color:#a95149}.hw-pill.green{background:#e9f8f3;color:#268473}.hw-pill.gray{background:#eef1f5;color:#69788a}.hw-bars{display:grid;gap:15px}.hw-barrow{display:grid;grid-template-columns:104px minmax(0,1fr) 74px;gap:12px;align-items:center;font-size:11px}.hw-barrow label{color:#4b5d6a}.hw-bartrack{height:10px;border-radius:10px;background:#edf2f5;overflow:hidden;position:relative}.hw-bartrack .supply{height:100%;background:#b9d7e7;border-radius:10px}.hw-bartrack .demand{height:5px;background:#2b88b4;position:absolute;top:2px;left:0;border-radius:10px}.hw-bartrack .excess{height:5px;background:#d88b66;position:absolute;top:2px;left:0;border-radius:10px}.hw-barrow b{text-align:right;font-size:11px}.hw-actions{display:grid;gap:0}.hw-action{display:flex;gap:13px;align-items:start;padding:12px 0;border-bottom:1px solid #eaf0f3}.hw-action:last-child{border:0}.hw-dot{width:9px;height:9px;background:#d79a54;border-radius:50%;margin-top:5px;flex-shrink:0}.hw-action b{display:block;font-weight:700;font-size:11px}.hw-action small{display:block;color:#82929f;font-size:10px}.hw-action p{margin:1px 0 0;color:#586d7b;font-size:11px}.hw-toolbar{display:flex;align-items:center;gap:10px;margin-bottom:14px;min-width:0}.hw-search{flex:1 1 180px;width:100%;min-width:100px;border:1px solid #d9e3eb;background:white;border-radius:8px;padding:10px 12px}.hw-toolbar .hw-btn{flex:none}.hw-filterline{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:13px}.hw-select{padding:9px 10px;border:1px solid #d9e3eb;border-radius:8px;background:white;color:#334b60}.hw-tablewrap{overflow-x:auto;max-width:100%}.hw-table{border-collapse:collapse;width:100%;min-width:690px}.hw-table th{font-size:10px;text-transform:uppercase;letter-spacing:.9px;color:#8292a2;font-weight:800;background:#f9fbfc;padding:12px 15px;border-bottom:1px solid #e2e9ef;text-align:left;white-space:nowrap}.hw-table td{padding:13px 15px;border-bottom:1px solid #eaf0f4;color:#536777;font-size:11px}.hw-table tbody tr:hover{background:#fafcfe}.hw-table td strong{color:#213b4b}.hw-table td:last-child{text-align:right}.hw-table tr:last-child td{border-bottom:0}.hw-menuwrap{display:inline-flex;position:relative}.hw-more{background:transparent;border:1px solid transparent;color:#5e7585;border-radius:7px;padding:3px 9px;font-size:19px;line-height:1}.hw-more:hover{background:#f2f5f8}.hw-menu{position:absolute;z-index:15;right:0;top:29px;width:142px;background:white;padding:5px;border:1px solid #dce5ea;border-radius:9px;box-shadow:0 15px 24px #102c3c22;text-align:left}.hw-menu button{background:transparent;border:0;border-radius:6px;padding:9px 10px;width:100%;text-align:left;font-size:11px;color:#415568}.hw-menu button:hover{background:#edf5f9}.hw-menu button.danger{color:#aa504f}.hw-foot{padding:12px 17px;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;font-size:11px;color:#8a99a6}.hw-timeline{overflow-x:auto;max-width:100%}.hw-timetable{min-width:810px;width:100%;border-collapse:separate;border-spacing:0;font-size:11px}.hw-timetable th{font-size:10px;color:#8999a6;text-transform:uppercase;letter-spacing:.8px;text-align:center;border-bottom:1px solid #e3ecf1;background:#f9fbfd;padding:15px 9px}.hw-timetable th:first-child{text-align:left;position:sticky;left:0;z-index:2;width:170px;background:#f9fbfd}.hw-timetable td{padding:10px 7px;border-bottom:1px solid #ecf1f5;vertical-align:middle;height:67px;text-align:center;position:relative}.hw-timetable td:first-child{position:sticky;left:0;z-index:1;background:white;text-align:left;padding-left:16px;border-right:1px solid #edf1f4}.hw-timetable td strong{display:block;color:#314759;font-size:11px}.hw-timetable td small{font-size:10px;color:#91a0aa}.hw-timelinebar{width:100%;display:block;border-radius:6px;padding:7px 3px;font-size:10px;font-weight:760;white-space:nowrap;background:#e9f2f8;color:#2b728f}.hw-timelinebar.free{background:#f3f7fa;color:#a5b5c1}.hw-timelinebar.over{background:#ffeddf;color:#a76236}.hw-timelinebar.place{background:#edf6f3;color:#258776;border:1px dashed #7ab8ab}.hw-legend{display:flex;gap:16px;flex-wrap:wrap;align-items:center;color:#738697;font-size:11px}.hw-legend i{display:inline-block;width:10px;height:10px;border-radius:3px;background:#2c8db6;margin-right:5px}.hw-forecast-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px;align-items:end;min-height:226px;border-bottom:1px solid #dce7ee;padding:18px 8px 0}.hw-monthcol{display:flex;align-items:center;flex-direction:column;justify-content:flex-end;height:204px;gap:4px}.hw-monthbars{display:flex;align-items:end;gap:3px;height:165px;width:100%;justify-content:center}.hw-monthbars span{display:block;width:28%;min-height:2px;border-radius:4px 4px 0 0}.hw-monthbars .capacity{background:#b1d2e5}.hw-monthbars .load{background:#267ba7}.hw-monthbars .load.over{background:#c77e61}.hw-monthcol small{font-size:10px;color:#8da0ac}.hw-monthcol b{font-size:10px;color:#476274}.hw-condensed{font-size:11px;color:#7d8d9d}.hw-steps{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px}.hw-stage{border-radius:11px;background:#f5f8fa;padding:11px 8px;min-height:330px;min-width:0}.hw-stage-head{display:flex;justify-content:space-between;align-items:center;gap:7px;padding:4px 7px 10px;border-bottom:1px solid #e0e9ef;margin-bottom:9px}.hw-stage-head strong{font-size:11px;color:#39536a}.hw-stage-head small{font-size:10px;color:#8294a4}.hw-stage-card{border-radius:9px;border:1px solid #e3e9ee;background:white;padding:11px;margin-bottom:8px;box-shadow:0 2px 6px #20435b06}.hw-stage-card b{display:block;font-size:11px}.hw-stage-card small{display:block;color:#80919f;font-size:10px}.hw-stage-card .hw-btn{margin-top:9px}.hw-scenario{display:grid;grid-template-columns:minmax(260px,.75fr) minmax(0,1.25fr);gap:14px}.hw-form{display:grid;gap:13px}.hw-field{font-size:11px;font-weight:660;color:#637789;display:grid;gap:5px}.hw-field input,.hw-field select,.hw-field textarea{width:100%;border:1px solid #dbe4eb;border-radius:8px;padding:10px;background:#fff;color:#293f51}.hw-field textarea{min-height:85px;resize:vertical}.hw-formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.hw-drawercover{position:fixed;z-index:31;inset:0;background:#0a223b77;display:flex;justify-content:flex-end}.hw-drawer{width:min(510px,100%);background:white;display:flex;flex-direction:column;min-height:100vh;max-height:100vh;box-shadow:-8px 0 32px #0002}.hw-drawerhead{padding:22px 25px;border-bottom:1px solid #e8eef1;display:flex;align-items:start;justify-content:space-between}.hw-drawerhead h2{font-size:19px;margin:0;letter-spacing:-.5px}.hw-drawerbody{padding:20px 25px;overflow:auto;flex:1}.hw-drawerfoot{padding:15px 25px;border-top:1px solid var(--line);display:flex;justify-content:flex-end;gap:10px}.hw-dialog{width:min(430px,calc(100vw - 30px));margin:auto;background:white;border-radius:13px;padding:25px}.hw-dialog h2{font-size:20px;margin:0 0 9px}.hw-dialog p{font-size:12px;color:#617384;line-height:1.6}.hw-gridnote{background:#f1f7fa;border:1px solid #dfebf2;border-radius:10px;padding:13px;color:#58758b;font-size:11px}.hw-settings{display:grid;grid-template-columns:1fr 1fr;gap:20px}.hw-layoutlist{display:grid;gap:8px}.hw-layoutrow{border:1px solid #dfe7eb;border-radius:8px;padding:10px 12px;display:flex;align-items:center;gap:12px;background:white;font-size:11px}.hw-layoutrow[draggable]{cursor:grab}.hw-layoutrow.pick{background:#e9f4fa;border-color:#8ac2dc}.hw-layoutrow .label{flex:1}.hw-layoutrow .grip{color:#8ba2af;font-size:18px}.hw-box{background:#f1f7fa;border:1px solid #e3edf2;border-radius:11px;padding:16px}.hw-empty{padding:38px 20px;text-align:center;color:#8796a4;font-size:12px}.hw-note{margin-top:17px;color:#95a3ad;font-size:10px}.hw-toast{background:#e8f5f4;color:#257770;padding:10px 13px;border-radius:8px;font-size:11px;margin-bottom:13px}.hw-broken{color:#a65249}.hw-link{color:#1b7c9f;background:none;border:0;padding:0;font-size:11px;text-decoration:underline;text-underline-offset:2px}.hw-stack{display:grid;gap:15px}.hw-report{background:#eff6f9;border-left:3px solid #3794af;padding:15px;color:#4d6776;font-size:12px;white-space:pre-wrap}.hw-split{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(220px,.8fr);gap:15px}.hw-progressbar{height:9px;background:#e7eff3;border-radius:8px;overflow:hidden}.hw-progressbar span{display:block;height:100%;background:#2d85a9}.hw-avoid{color:#af5b40;font-weight:700}
@media(max-width:1100px){.hw-shell{grid-template-columns:66px minmax(0,1fr)}.hw-headbrand{padding:8px 0 16px;text-align:center}.hw-headbrand small,.hw-appbrand,.hw-railcaption,.hw-nav span,.hw-rail-foot{display:none!important}.hw-nav button{justify-content:center}.hw-sidebar{padding:18px 9px}.hw-grid2,.hw-scenario{grid-template-columns:1fr}.hw-grid{grid-template-columns:repeat(3,1fr)}}
@media(max-width:700px){.hw-shell{display:block}.hw-sidebar{padding:8px 12px}.hw-headbrand{display:none}.hw-railcaption,.hw-rail-foot{display:none}.hw-nav{display:flex;flex-direction:row;overflow-x:auto}.hw-nav button{width:auto;padding:9px;flex:none}.hw-main{padding:20px 14px 40px}.hw-top{flex-direction:column;gap:12px}.hw-top-actions{align-self:stretch;justify-content:flex-end}.hw-grid{grid-template-columns:1fr 1fr}.hw-hero{grid-column:span 2}.hw-steps{display:flex;overflow-x:auto;padding:4px}.hw-stage{min-width:200px}.hw-gridEqual,.hw-split,.hw-settings{grid-template-columns:1fr}.hw-formgrid{grid-template-columns:1fr}.hw-forecast-grid{gap:3px}.hw-monthbars span{width:44%}.hw-metric{min-height:132px;padding:17px}.hw-metric strong{font-size:27px;margin:9px 0}.hw-timetable{min-width:710px}}@media(max-width:380px){.hw-grid{grid-template-columns:1fr}.hw-hero{grid-column:span 1}.hw-top h1{font-size:24px}}

/* Biotech Hiring & Resource Management 1.4: vivid, lean biotech teams. Contrast-driven; not enterprise HR UI. */
:root{--hw:#f8f8ff;--ink:#182044;--nav:#111a3e;--ocean:#6356ed;--teal:#00a8b6;--line:#e6e8fa;--muted:#707997;--sun:#ffae63;--bad:#e05c70;--radius:18px}
body{background:var(--hw);color:var(--ink);font-size:13px}
.hw-shell{grid-template-columns:232px minmax(0,1fr)}
.hw-sidebar{background:linear-gradient(171deg,#151b48 0%,#241856 58%,#15234a 100%);border-right:1px solid #29265e;padding:30px 17px 23px}
.hw-headbrand{border-color:#ffffff22;padding-bottom:26px;margin-bottom:4px}
.hw-appbrand{font-size:26px;font-weight:850;letter-spacing:-1.4px;line-height:1.0}
.hw-appbrand span{color:#fff}.hw-appbrand em{font-style:normal;color:#b7f66f}
.hw-appbrand small{color:#aca7ff;letter-spacing:1.35px;font-size:8px;line-height:1.5;margin-bottom:14px;max-width:150px}
.hw-railcaption{color:#a7a6d3;font-size:9px;letter-spacing:1.9px}
.hw-nav{gap:5px}
.hw-nav button{padding:12px 13px;font-size:12px;color:#c4c5e5;border-radius:12px;transition:background .15s,color .15s}
.hw-nav button.current{background:linear-gradient(100deg,#7362fc,#4c56d8);box-shadow:0 8px 20px #0b123e70;color:#fff;font-weight:760}
.hw-nav button:hover:not(.current){background:#ffffff11;color:#fff}
.hw-rail-foot{border-color:#ffffff22;color:#a7acd4;font-size:10px;line-height:1.7}
.hw-rail-foot b{color:#bdf881;font-size:11px}
.hw-main{max-width:1460px;padding:34px clamp(22px,3.2vw,48px) 65px}
.hw-kicker{color:#665bea;font-size:9px;letter-spacing:1.8px}
.hw-top{margin-bottom:22px}
.hw-top h1{font-size:clamp(26px,3vw,35px);font-weight:820;color:#1a2050}
.hw-sub{color:#72799d;font-size:12px}
.hw-select,.hw-search,.hw-field input,.hw-field select,.hw-field textarea{border-color:#dedff2;border-radius:11px;box-shadow:0 1px 3px #4950a508}
.hw-btn,.hw-ico{border-color:#e1e2f4;color:#4a4b82;border-radius:11px;font-weight:700;box-shadow:0 2px 7px #514bc009}
.hw-btn:hover:not(:disabled),.hw-ico:hover{border-color:#a79cfb;background:#f2f0ff}
.hw-btn.primary{background:linear-gradient(110deg,#6c55f3,#504ad5);border-color:#5c52e7;color:#fff;box-shadow:0 6px 14px #6559ec26}
.hw-btn.primary:hover:not(:disabled){background:linear-gradient(110deg,#765fff,#5a51e5);color:#fff}
.hw-panel{border:1px solid #e8e8f6;border-radius:17px;box-shadow:0 7px 25px #40438c09}
.hw-pad{padding:21px}
.hw-section-head h2{font-size:15px;font-weight:790;color:#1b2250}
.hw-section-head p{color:#858ba9}
.hw-grid{gap:15px}
.hw-hero{background:linear-gradient(135deg,#30206f 0%,#6044de 75%,#7352fc);color:white;border:0;min-height:166px;padding:23px}
.hw-hero:after{width:250px;height:250px;right:-50px;top:-150px;border:1px solid #ffffff40;box-shadow:0 0 0 33px #ffffff0f,0 0 0 66px #ffffff07}
.hw-hero small{color:#e2dbff}
.hw-hero p{color:#e5deff}
.hw-hero .hw-big{font-size:43px}
.hw-metric{min-height:166px;padding:22px}
.hw-metric.violet{background:linear-gradient(157deg,#f0edff,#fff 74%);border-color:#e6e2ff}
.hw-metric.coral{background:linear-gradient(150deg,#fff0ea,#fff 75%);border-color:#ffe9dd}
.hw-metric .label{color:#555e8e}
.hw-metric strong{font-weight:840;color:#342485;font-size:37px;margin:11px 0 6px}
.hw-metric.coral strong{color:#d96355}
.hw-metric small{color:#8486a1}
.hw-unit{font-size:15px;font-weight:600!important;letter-spacing:0;color:inherit;opacity:.75}
.hw-welcome{background:linear-gradient(113deg,#d6fbf3,#e2eeff 50%,#f3e4ff);border:1px solid #d5e2fa;border-radius:20px;padding:18px 25px;margin-bottom:17px;position:relative;overflow:hidden}
.hw-mini-label{display:inline-flex;background:white;padding:5px 10px;border-radius:30px;color:#5f53ba;letter-spacing:1.15px;font-size:9px;font-weight:840}
.hw-welcome-row{display:flex;align-items:center;justify-content:space-between;gap:15px}
.hw-welcome h2{font-size:27px;letter-spacing:-1px;font-weight:850;line-height:1.1;margin:13px 0 6px;color:#24215f}
.hw-welcome p{color:#686e92;margin:0;font-size:12px;max-width:600px}
.hw-welcome-graphic{width:81px;height:81px;border-radius:23px;background:#ffffff9c;display:grid;place-items:center;transform:rotate(-9deg);color:#6b50e2;box-shadow:0 7px 14px #605cd020;flex-shrink:0}
.hw-grid2{grid-template-columns:1.18fr 1fr;gap:16px;margin-top:16px}
.hw-bars{gap:17px}.hw-barrow{grid-template-columns:95px minmax(0,1fr) 80px}
.hw-bartrack{height:12px;background:#eeedfd}
.hw-bartrack .supply{background:#a6ddec}.hw-bartrack .demand{background:#6253f5;height:6px;top:3px}.hw-bartrack .excess{background:#ff7f69;height:6px;top:3px}
.hw-study{display:flex;align-items:center;gap:11px;padding:13px 7px;border-bottom:1px solid #edf0fa}
.hw-study:last-child{border:0}.hw-study-accent{width:8px;height:35px;border-radius:20px;background:#6b56f4;flex:0 0 auto}
.hw-study:nth-child(2) .hw-study-accent{background:#09bbc7}.hw-study:nth-child(3) .hw-study-accent{background:#ff866f}.hw-study:nth-child(4) .hw-study-accent{background:#a6ce54}
.hw-study div:nth-child(2){flex:1;min-width:0}.hw-study strong,.hw-study small{display:block}.hw-study strong{color:#303368;font-size:11px}.hw-study small{font-size:10px;color:#9597af;margin-top:3px}.hw-study b{color:#534ac4;font-size:12px;white-space:nowrap}
.hw-next-actions{display:flex;gap:16px;flex-wrap:wrap}.hw-next-actions .hw-action{border:1px solid #eeeafb;background:#fbfaff;border-radius:13px;flex:1;min-width:175px;padding:13px}.hw-dot{background:#ff8b65}
.hw-pill{background:#f0edff;color:#5e50c8}.hw-pill.warn{background:#fff1d9;color:#9d6725}.hw-pill.red{background:#ffedec;color:#bd4d5a}.hw-pill.green{background:#e4f9f0;color:#248f7c}
