function table(role,keys=baseCols[role],filterFn=()=>true){let list=rr(role).filter(filterFn),q=ns.query.toLowerCase().trim();if(q)list=list.filter(r=>Object.values(r.data).some(v=>String(v??'').toLowerCase().includes(q)));if(ns.filter!=='All')list=list.filter(r=>Object.values(r.data).some(v=>String(v)===ns.filter));const size=Math.max(10,Math.min(25,number(cfg.pageSize,25))),pages=Math.max(1,Math.ceil(list.length/size));ns.page=Math.min(pages-1,ns.page);let pageRows=list.slice(ns.page*size,(ns.page+1)*size);let cols=ns.layout.cols[role]||keys;cols=cols.filter(k=>ns.layout.visible[role+':'+k]!==false).slice(0,8);if(!cols.length)cols=[keys[0]];const headers=cols.map(k=>'<th>'+esc(defs[role].find(x=>x[0]===k)?.[1]||k)+'</th>').join('');let body=pageRows.map(r=>'<tr>'+cols.map(k=>{let v=r.data[k];if(k==='personId'&&v)v=label('staff',v);if(k==='projectId'&&v)v=label('projects',v);let txt=k==='fte'?fmt(number(v,null)):['status','stage','priority','consentStatus'].includes(k)?pill(v):esc(v===null||v===undefined||v===''?'—':v);return '<td>'+(k===cols[0]?'<strong>'+txt+'</strong>':txt)+'</td>';}).join('')+'<td>'+actionMenu(role,r)+'</td></tr>').join('');return '<div class="hw-panel"><div class="hw-tablewrap"><table class="hw-table"><thead><tr>'+headers+'<th>Actions</th></tr></thead><tbody>'+(body||'<tr><td colspan="'+(cols.length+1)+'" class="hw-empty">No matching records</td></tr>')+'</tbody></table></div><div class="hw-foot"><span>'+list.length+' shown · '+(fetched[role].complete?'complete source':'partial source')+'</span><span>'+button('Previous','pg|'+(ns.page-1),'hw-btn small',ns.page===0?'disabled':'')+' &nbsp; '+(ns.page+1)+' / '+pages+' &nbsp; '+button('Next','pg|'+(ns.page+1),'hw-btn small',ns.page>=pages-1?'disabled':'')+'</span></div></div>';}
function toolbar(role,placeholder='Search records'){return '<div class="hw-toolbar"><input type="search" class="hw-search" aria-label="Search records" placeholder="'+esc(placeholder)+'" data-ui-state="true" data-action="search" value="'+esc(ns.query)+'">'+button(icon('plus')+' Add record','new|'+role,'hw-btn primary',!canWrite(role)?'disabled':'')+'</div>';}
function sectionTitle(a,b=''){return '<div class="hw-section-head"><h2>'+esc(a)+'</h2></div>';}
if(ea==='select-month')ns.month=mo(ev.value)||ns.month;
const monthOptions=[...new Set([-1,0,1,2,3,4,5,6].map(x=>addMo(thisMonth,x)).concat(ns.month))].sort().map(m=>{return '<option value="'+m+'"'+(m===ns.month?' selected':'')+'>'+dateLabel(m)+'</option>';}).join('');
function overview(){const curr=rollup(ns.month);const specialties=['Discovery R&D','Preclinical','CMC','Clinical Development','Regulatory','Quality','BD & Finance','Operations'];const activeActivities=activeProjects.length;
const pctUsed=curr.supply?Math.round(curr.assigned/curr.supply*100):0;
const active=activeProjects.slice(0,4).map(p=>{const demand=rr('allocations').filter(x=>x.data.projectId===p.id&&isIn(x,ns.month)).reduce((v,x)=>v+number(x.data.fte),0);return '<div class="hw-study"><div class="hw-study-accent"></div><div><strong>'+esc(p.data.name)+'</strong><small>'+esc(p.data.activityType||'Activity')+'  /  '+esc(p.data.program||'')+'</small></div><b>'+fmt(demand)+' FTE</b></div>';}).join('');
const cards='<div class="hw-grid"><article class="hw-panel hw-hero"><small>Available this month</small><div class="hw-big">'+fmt(curr.supply)+' <span class="hw-unit">FTE</span></div><p>'+visiblePeople.length+' people  ·  Employees + contractors</p></article><article class="hw-panel hw-metric violet"><span class="label">Project workload</span><strong>'+fmt(curr.demand)+' <span class="hw-unit">FTE</span></strong><small>'+pctUsed+'% allocated to named staff</small></article><article class="hw-panel hw-metric coral"><span class="label">Unfilled role demand</span><strong>'+fmt(curr.placeholders)+' <span class="hw-unit">FTE</span></strong><small>'+curr.overloaded.length+' overbooked people · '+activeActivities+' active / planned activities</small></article></div>';
const bars=specialties.map(fn=>{const v=rollup(ns.month,fn),mx=Math.max(.1,v.demand,v.supply);return '<div class="hw-barrow"><label>'+esc(fn)+'</label><div class="hw-bartrack"><span class="supply" style="display:block;width:'+Math.round(v.supply/mx*100)+'%"></span><span class="'+(v.demand>v.supply?'excess':'demand')+'" style="width:'+Math.min(100,Math.round(v.demand/mx*100))+'%"></span></div><b class="'+(v.demand>v.supply?'hw-badtext':'')+'">'+fmt(v.demand)+' / '+fmt(v.supply)+'</b></div>';}).join('');
const pending=rr('requests').filter(x=>['Pending','Approved'].includes(x.data.status)).slice(0,3).map(x=>'<div class="hw-action"><span class="hw-dot"></span><div><b>'+esc(x.data.role||x.data.name)+'</b><small>'+pill(x.data.status)+' · '+fmt(x.data.fte)+' FTE · '+esc(x.data.targetStart||'unscheduled')+'</small></div></div>').join('');
return cards+'<div class="hw-grid2"><div class="hw-panel hw-pad">'+sectionTitle('Where the work is','Monthly FTE demand / available capacity by specialty')+'<div class="hw-bars">'+bars+'</div></div><div class="hw-panel hw-pad">'+sectionTitle('Active priorities','Where your team is spending time this month')+'<div class="hw-studies">'+(active||'<p class="hw-condensed">Add your first project</p>')+'</div></div></div><div class="hw-panel hw-pad" style="margin-top:16px">'+sectionTitle('Decisions this month','Keep the next hires and gaps clear, not buried in an HR system')+'<div class="hw-next-actions">'+(pending||'<span class="hw-condensed">No decisions need review</span>')+'</div></div><p class="hw-note">Planned hires and placeholders never count as available staff. '+(Object.values(fetched).some(p=>!p.complete)?'Some source reads are incomplete.':'')+'</p>';}
function people(){let header=sectionTitle('Our biotech team','Scientists, clinical, CMC, regulatory and business specialists');const chips=['All','Discovery R&D','Preclinical','CMC','Clinical Development','Regulatory','Quality','BD & Finance','Operations'].map(x=>button(x,'filter|'+x,'hw-btn small'+(ns.filter===x?' primary':''))).join(' ');return toolbar('staff','Search specialists, role or skills')+'<div class="hw-filterline">'+chips+'</div>'+table('staff');}
function planner(){if(ns.plannerView==='activities')return button('Back to assignments','planner-view')+toolbar('projects','Search activities')+table('projects');const months=Array.from({length:6},(_,i)=>addMo(ns.month,i));const staff=rr('staff').filter(x=>x.data.status!=='Inactive');const pl=rr('allocations').filter(x=>!x.data.personId);const unique=pl.filter((x,i,a)=>a.findIndex(z=>z.data.placeholderRole===x.data.placeholderRole)===i);const resources=staff.map(person=>({person})).concat(unique.map(placeholder=>({placeholder})));const pages=Math.max(1,Math.ceil(resources.length/25));ns.timelinePage=Math.max(0,Math.min(pages-1,number(ns.timelinePage)));const shown=resources.slice(ns.timelinePage*25,(ns.timelinePage+1)*25);const rows=shown.filter(x=>x.person).map(x=>x.person).map(person=>'<tr><td><strong>'+esc(person.data.name)+'</strong><small>'+esc(person.data.function||'')+' · '+fmt(person.data.fte)+' FTE</small></td>'+months.map(m=>{const v=rr('allocations').filter(x=>x.data.personId===person.id&&isIn(x,m)).reduce((s,x)=>s+number(x.data.fte),0),cap=availability(person,m);return '<td><span class="hw-timelinebar '+(v>cap?'over':v?'':'free')+'">'+(v?fmt(v)+' / '+fmt(cap)+' FTE':'Available '+fmt(cap))+'</span></td>';}).join('')+'</tr>').join('');let ph=shown.filter(x=>x.placeholder).map(x=>x.placeholder).map(x=>'<tr><td><strong>'+esc(x.data.placeholderRole||'Unfilled role')+'</strong><small>Unmet / placeholder demand</small></td>'+months.map(m=>'<td>'+(pl.some(z=>z.data.placeholderRole===x.data.placeholderRole&&isIn(z,m))?'<span class="hw-timelinebar place">'+fmt(pl.filter(z=>z.data.placeholderRole===x.data.placeholderRole&&isIn(z,m)).reduce((q,z)=>q+number(z.data.fte),0))+' FTE need</span>':'')+'</td>').join('')+'</tr>').join('');return '<div class="hw-panel hw-pad"><div class="hw-filterline">'+button('← Previous month','month|'+addMo(ns.month,-1),'hw-btn small')+button('Next month →','month|'+addMo(ns.month,1),'hw-btn small')+button('Manage activities','planner-view','hw-btn small')+button('Add allocation','new|allocations','hw-btn primary small',!canWrite('allocations')?'disabled':'')+'</div><div class="hw-timeline"><table class="hw-timetable"><thead><tr><th>Resource / role</th>'+months.map(m=>'<th>'+dateLabel(m)+'</th>').join('')+'</tr></thead><tbody>'+(rows+ph||'<tr><td>No people</td></tr>')+'</tbody></table></div><div class="hw-foot"><span>'+resources.length+' resources · Page '+(ns.timelinePage+1)+' of '+pages+'</span><span>'+button('Previous resources','timeline-page|'+(ns.timelinePage-1),'hw-btn small',ns.timelinePage===0?'disabled':'')+button('Next resources','timeline-page|'+(ns.timelinePage+1),'hw-btn small',ns.timelinePage===pages-1?'disabled':'')+'</span></div><div class="hw-legend" style="margin-top:16px"><span><i></i> Allocated</span><span><i style="background:#d38e5c"></i> Over capacity</span><span><i style="background:#3b9986"></i> Unfilled-role placeholder</span></div></div><div style="margin-top:15px">'+sectionTitle('Project assignments','Edit a person, activity and month with reviewed record changes')+toolbar('allocations','Activity, person or open role')+table('allocations',baseCols.allocations,x=>mo(x.data.month)===ns.month)+'</div>';}
function forecast(){const months=Array.from({length:ns.horizon},(_,i)=>addMo(ns.month,i)),vals=months.map(m=>rollup(m)),max=Math.max(1,...vals.map(x=>Math.max(x.supply,x.demand))),graph='<div class="hw-forecast-grid">'+months.slice(0,12).map((m,i)=>{const x=vals[i],h=n=>Math.round(n/max*155)+'px';return '<div class="hw-monthcol"><div class="hw-monthbars"><span class="capacity" style="height:'+h(x.supply)+'"></span><span class="load '+(x.demand>x.supply?'over':'')+'" style="height:'+h(x.demand)+'"></span></div><b>'+dateLabel(m)+'</b><small>'+fmt(x.shortage)+' gap</small></div>';}).join('')+'</div>';let gaps=months.filter(m=>rollup(m).shortage>.001);return '<div class="hw-panel hw-pad"><div class="hw-filterline">'+[3,6,12].map(n=>button(n+' months','horizon|'+n,'hw-btn small'+(ns.horizon===n?' primary':''))).join('')+'</div>'+graph+'<div class="hw-legend" style="margin-top:15px"><span><i style="background:#b1d2e5"></i> Available</span><span><i style="background:#267ba7"></i> Demand</span><span><i style="background:#c77e61"></i> Shortfall</span></div></div><div class="hw-gridEqual" style="margin-top:15px"><div class="hw-panel hw-pad">'+sectionTitle('Shortage outlook')+'<div class="hw-big" style="color:#be6751">'+gaps.length+' <span style="font-size:14px;color:#8395a3">months</span></div><p class="hw-condensed">'+(gaps.length?'First shortage '+esc(dateLabel(gaps[0])):'No shortage found in this horizon')+'. Includes saved unfilled-role placeholders.</p></div><div class="hw-panel hw-pad">'+sectionTitle('Interpretation rules')+'<p class="hw-condensed">Supply excludes future hires until they become active staff or are explicitly modeled in a scenario. Placeholders add unmet demand and never supply. Missing availability is not silently treated as full capacity.</p></div></div>'+(fetched.allocations.complete&&fetched.staff.complete?'':'<p class="hw-broken">Data incomplete: forecast may omit source rows.</p>');}
function requests(){return '<div class="hw-split"><div>'+toolbar('requests','Search requested roles')+table('requests')+'</div><div class="hw-panel hw-pad">'+sectionTitle('Small-team decisions','Approved and pending hiring or contractor needs')+'<div class="hw-actions">'+rr('requests').filter(x=>['Pending','Approved'].includes(x.data.status)).slice(0,9).map(x=>'<div class="hw-action"><span class="hw-dot"></span><div><b>'+esc(x.data.role||x.data.name)+'</b><small>'+pill(x.data.status)+' · '+fmt(x.data.fte)+' FTE · '+esc(x.data.targetStart||'No date')+'</small></div></div>').join('')+'</div></div></div>';}

function scenarios(){const scenario=rr('scenarios').find(x=>x.id===ns.scenarioId)?.data||{name:'Baseline',hireShiftMonths:0,hiringFte:0,contractorFte:0,};const months=Array.from({length:6},(_,i)=>addMo(ns.month,i));const first=months.map(m=>rollup(m)),next=months.map(m=>rollup(m,'',scenario));const deficit=v=>v.reduce((s,x)=>s+(x.shortage>.01?1:0),0);const scselect='<select class="hw-select" aria-label="Scenario" data-ui-state="true" data-action="scenario-select"><option value="baseline"'+(ns.scenarioId==='baseline'?' selected':'')+'>Baseline</option>'+rr('scenarios').map(x=>'<option value="'+esc(x.id)+'"'+(ns.scenarioId===x.id?' selected':'')+'>'+esc(x.data.name)+'</option>').join('')+'</select>';let c='<div class="hw-scenario"><div class="hw-panel hw-pad"><div class="hw-field">Scenario'+scselect+'</div><div class="hw-box" style="margin-top:14px"><b>'+esc(scenario.name)+'</b><p class="hw-condensed">Hire shift: '+fmt(number(scenario.hireShiftMonths))+' mo · +'+fmt(number(scenario.hiringFte))+' hired FTE · +'+fmt(number(scenario.contractorFte))+' contractors</p></div>'+button('Add scenario','new|scenarios','hw-btn primary','style="margin-top:14px"')+'</div><div class="hw-panel hw-pad">'+sectionTitle('6-month scenario impact','Calculated from the same baseline allocations')+'<div class="hw-gridEqual"><div class="hw-box"><small>Baseline shortage months</small><div class="hw-big">'+deficit(first)+'</div></div><div class="hw-box"><small>Scenario shortage months</small><div class="hw-big">'+deficit(next)+'</div></div></div><div class="hw-tablewrap" style="margin-top:16px"><table class="hw-table"><thead><tr><th>Month</th><th>Baseline gap</th><th>Scenario gap</th></tr></thead><tbody>'+months.map((m,i)=>'<tr><td>'+esc(dateLabel(m))+'</td><td>'+fmt(first[i].shortage)+' FTE</td><td>'+fmt(next[i].shortage)+' FTE</td></tr>').join('')+'</tbody></table></div></div></div><div style="margin-top:15px">'+sectionTitle('Saved team capacity options','Compare hiring decisions without changing existing allocations')+toolbar('scenarios','Scenario name')+table('scenarios');return c;}

const routes={overview,people,planner,forecast,requests,scenarios};
if(ea==='scenario-select')ns.scenarioId=String(ev.value||'baseline');
function dialog(){if(!ns.dialog)return '';const d=ns.dialog; if(d.type==='delete'){const r=find(d.role,d.id);return '<div class="hw-drawercover"><section class="hw-dialog" role="dialog" aria-label="Delete record"><h2>Archive this record?</h2><p>'+esc(r?.data.name||'This record')+' will disappear from this app view after approval. Its database ID, history and other access paths are retained. No physical deletion is performed.</p>'+button('Cancel','close')+' '+button('Review archive','confirm-delete','hw-btn primary')+'</section></div>';}
 if(d.type==='form'){const ddata=d.draft||{};return '<div class="hw-drawercover"><div class="hw-drawer"><div class="hw-drawerhead"><div><small class="hw-kicker">Reviewed record edit</small><h2>'+(d.duplicate?'Duplicate ':d.id?'Edit ':'New ')+esc(d.role)+'</h2></div>'+button(icon('close'),'close','hw-ico','aria-label="Close"')+'</div><form class="hw-drawerbody hw-form" id="hw-edit" data-action="save-record">'+fieldsForm(d.role,ddata)+'<button type="submit" class="hw-btn primary">Prepare for review</button></form><div class="hw-drawerfoot">'+button('Cancel','close')+'</div></div></div>';}}
if(ns.layout.visible[ns.screen]===false)ns.screen=ns.layout.tabs.find(id=>ns.layout.visible[id]!==false)||'overview';
const sidebar='<aside class="hw-sidebar"><div class="hw-headbrand"><div class="hw-appbrand"><span>'+esc(ns.layout.heading)+'</span></div></div><nav class="hw-nav">'+ns.layout.tabs.filter(id=>ns.layout.visible[id]!==false).map(id=>{const s=ss.find(s=>s.id===id);return button(icon(id)+' <span>'+esc(s.label)+'</span>','nav|'+id,'hw-btn','aria-current="'+(ns.screen===id?'page':'false')+'"').replace('class="hw-btn"','class="'+(ns.screen===id?'current':'')+'"');}).join('')+'</nav></aside>';
const cur=ss.find(x=>x.id===ns.screen),title=cur.label;
const top='<div class="hw-top"><h1>'+esc(title)+'</h1><div class="hw-top-actions"><select class="hw-select" aria-label="Planning month" data-ui-state="true" data-action="select-month">'+monthOptions+'</select>'+button(icon('settings'),'tracker:layout','hw-ico','aria-label="Layout settings"'+(!input.saved?' disabled':''))+'</div></div>';
const scenarioReady=fetched.scenarios.complete&&rr('scenarios').every(r=>['hireShiftMonths','hiringFte','contractorFte'].every(k=>numeric(r.data[k]))&&Number.isInteger(number(r.data.hireShiftMonths)));
const blocked=['overview','planner','forecast','scenarios'].includes(ns.screen)&&(!capacityReady||(ns.screen==='scenarios'&&!scenarioReady));
const body=blocked?(ns.screen==='planner'?button('Manage activities','planner-view')+toolbar(ns.plannerView==='activities'?'projects':'allocations')+table(ns.plannerView==='activities'?'projects':'allocations'):ns.screen==='scenarios'?toolbar('scenarios','Scenario name')+table('scenarios'):''):routes[ns.screen]();
const notice=ns.notice?'<div class="hw-toast" role="status">'+esc(ns.notice)+'</div>':'';
const sourceWarning=blocked?'<p role="status" class="hw-gridnote">Some data is unavailable, incomplete or invalid. Capacity totals and forecasts are withheld until required authorized records and values are complete. Review People, Activities, Allocations and scenario assumptions; missing data is not zero capacity.</p>':Object.values(fetched).some(p=>!p.complete)?'<p role="status" class="hw-gridnote">Some record lists are incomplete or unavailable. Do not treat these lists as complete sources.</p>':'';
return {html:'<div class="hw-shell">'+sidebar+'<main class="hw-main">'+top+sourceWarning+notice+body+(cfg.demoLabel?'<p class="hw-demo-note">Fictional example data · not a live workspace.</p>':'')+'</main></div>'+dialog(),css:HIRING_CSS,state:ns};
